const e="n2-test-1",t="N2",n="JLPT N2 Practice Test 1",o={vocabulary:{timeLimit:35,questions:[{id:"v1",type:"kanji-reading",question:"彼の意見には【矛盾】がある。",options:["むじゅん","むじゅん","むどん","むとん"],correctAnswer:0,explanation:"矛盾 (むじゅん) means 'contradiction'."},{id:"v2",type:"kanji-reading",question:"この地域の【資源】は限られている。",options:["しげん","じげん","しがん","じがん"],correctAnswer:0,explanation:"資源 (しげん) means 'resources'."},{id:"v3",type:"kanji-reading",question:"新しい製品を【評価】する。",options:["ひょうか","ひょか","ひょうが","ひょが"],correctAnswer:0,explanation:"評価 (ひょうか) means 'evaluation / assessment'."},{id:"v4",type:"kanji-reading",question:"社会に【貢献】したい。",options:["こうけん","こけん","こうげん","こげん"],correctAnswer:0,explanation:"貢献 (こうけん) means 'contribution'."},{id:"v5",type:"kanji-reading",question:"彼は【豊富】な知識を持っている。",options:["ほうふ","ほうぶ","ほうふう","ほうぶう"],correctAnswer:0,explanation:"豊富 (ほうふ) means 'abundant / rich'."},{id:"v6",type:"kanji-reading",question:"若者の【傾向】を分析する。",options:["けいこう","けいごう","けんこう","けんごう"],correctAnswer:0,explanation:"傾向 (けいこう) means 'trend / tendency'."},{id:"v7",type:"kanji-reading",question:"地球環境への【影響】を考える。",options:["えいきょう","えいきょ","えんきょう","えんきょ"],correctAnswer:0,explanation:"影響 (えいきょう) means 'influence / effect'."},{id:"v8",type:"kanji-reading",question:"冷静に【判断】する。",options:["はんだん","はんたん","ばんたん","ばんだん"],correctAnswer:0,explanation:"判断 (はんだん) means 'judgment'."},{id:"v9",type:"kanji-reading",question:"あの人は【率直】に意見を言う。",options:["そっちょく","そつちょく","りっちょく","りつちょく"],correctAnswer:0,explanation:"率直 (そっちょく) means 'frank / candid'."},{id:"v10",type:"kanji-reading",question:"【納得】がいくまで話し合う。",options:["なっとく","なつとく","のうとく","のつとく"],correctAnswer:0,explanation:"納得 (なっとく) means 'consent / understanding'."},{id:"v11",type:"orthography",question:"【しょくば】の人間関係に悩む。",options:["職場","職庭","識場","識庭"],correctAnswer:0,explanation:"職場 (しょくば) is the kanji for workplace."},{id:"v12",type:"orthography",question:"【しょうさい】なデータを集める。",options:["詳細","少細","詳最","少最"],correctAnswer:0,explanation:"詳細 (しょうさい) is the kanji for details."},{id:"v13",type:"orthography",question:"新しいシステムを【どうにゅう】する。",options:["導入","動入","道入","同入"],correctAnswer:0,explanation:"導入 (どうにゅう) is the kanji for introduction/installation."},{id:"v14",type:"orthography",question:"【かつやく】を期待している。",options:["活躍","活役","活躍","活約"],correctAnswer:0,explanation:"活躍 (かつやく) is the kanji for active participation / success."},{id:"v15",type:"orthography",question:"【てきかく】なアドバイスをする。",options:["的確","適角","敵確","摘角"],correctAnswer:0,explanation:"的確 (てきかく) is the kanji for precise/accurate."},{id:"v16",type:"orthography",question:"【しゅうしゅう】がつかない状態だ。",options:["収拾","収集","秋収","習集"],correctAnswer:0,explanation:"収拾 (しゅうしゅう) is the kanji for getting under control / settling."},{id:"v17",type:"orthography",question:"【ふきゅう】活動に力を入れる。",options:["普及","不休","付給","府球"],correctAnswer:0,explanation:"普及 (ふきゅう) is the kanji for diffusion/spread."},{id:"v18",type:"context",question:"彼は（　　）があるので、どんな困難にも負けない。",options:["忍耐力","想像力","記憶力","集中力"],correctAnswer:0,explanation:"忍耐力 (にんたいりょく) means 'endurance / perseverance', needed to overcome difficulties."},{id:"v19",type:"context",question:"その話は（　　）が良すぎる。何か裏があるのではないか。",options:["都合","具合","調子","機嫌"],correctAnswer:0,explanation:"都合がいい (つごうがいい) here means 'too good to be true'."},{id:"v20",type:"context",question:"この計画は（　　）からやり直したほうがいい。",options:["白紙","黒板","青空","赤字"],correctAnswer:0,explanation:"白紙から (はくしから) is an idiom meaning 'from scratch / a blank slate'."},{id:"v21",type:"context",question:"会議で意見が（　　）して、なかなか結論が出なかった。",options:["対立","独立","孤立","成立"],correctAnswer:0,explanation:"対立 (たいりつ) means 'opposition / conflict', which prevents reaching a conclusion."},{id:"v22",type:"context",question:"彼は（　　）もなく、いきなり部屋に入ってきた。",options:["断り","頼み","願い","謝り"],correctAnswer:0,explanation:"断りもなく (ことわりもなく) means 'without asking permission / without notice'."},{id:"v23",type:"context",question:"そんな（　　）な言い方をしないで、はっきり言ってください。",options:["あいまい","あざやか","さわやか","なだらか"],correctAnswer:0,explanation:"曖昧 (あいまい) means 'vague / ambiguous'."},{id:"v24",type:"context",question:"彼女はいつも（　　）に満ちた顔をしている。",options:["自信","自身","自慢","自覚"],correctAnswer:0,explanation:"自信 (じしん) に満ちた = full of confidence."},{id:"v25",type:"context",question:"雨で試合が（　　）になった。",options:["延期","延長","長期","短期"],correctAnswer:0,explanation:"延期 (えんき) means 'postponement'."},{id:"v26",type:"context",question:"彼は仕事に対してとても（　　）だ。",options:["熱心","安心","関心","感心"],correctAnswer:0,explanation:"熱心 (ねっしん) means 'enthusiastic / eager'."},{id:"v27",type:"context",question:"この本は、初心者を（　　）に書かれている。",options:["対象","対照","対称","隊商"],correctAnswer:0,explanation:"対象 (たいしょう) means 'target / object'."},{id:"v28",type:"context",question:"ストレスが（　　）、体調を崩してしまった。",options:["たまって","あまって","つまって","とまって"],correctAnswer:0,explanation:"ストレスがたまる means 'stress accumulates'."},{id:"v29",type:"context",question:"彼は（　　）を尽くして患者を治療した。",options:["ベスト","トップ","リード","ゴール"],correctAnswer:0,explanation:"ベストを尽くす (to do one's best)."},{id:"v30",type:"paraphrase",question:"彼は【あらかじめ】準備をしておいた。",options:["事前に","事後に","同時に","直前に"],correctAnswer:0,explanation:"あらかじめ means 'in advance' (事前に)."},{id:"v31",type:"paraphrase",question:"この機械は【たびたび】故障する。",options:["何度も","一度も","たまに","急に"],correctAnswer:0,explanation:"たびたび means 'often / repeatedly' (何度も)."},{id:"v32",type:"paraphrase",question:"彼は【わざと】負けたようだ。",options:["意図的に","偶然に","仕方なく","突然"],correctAnswer:0,explanation:"わざと means 'on purpose' (意図的に)."},{id:"v33",type:"paraphrase",question:"それは【思いがけない】出来事だった。",options:["予想外の","予想通りの","当然の","いつもの"],correctAnswer:0,explanation:"思いがけない means 'unexpected' (予想外の)."},{id:"v34",type:"paraphrase",question:"彼女は【そわそわしている】。",options:["落ち着かない様子だ","怒っている様子だ","悲しんでいる様子だ","疲れている様子だ"],correctAnswer:0,explanation:"そわそわする means 'to be restless / fidgety' (落ち着かない)."},{id:"v35",type:"paraphrase",question:"計画は【順調】に進んでいる。",options:["問題なく","遅れて","止まって","急いで"],correctAnswer:0,explanation:"順調 (じゅんちょう) means 'smoothly / without a hitch' (問題なく)."},{id:"v36",type:"paraphrase",question:"彼の説明は【妥当】だ。",options:["適切だ","不適切だ","長すぎる","短すぎる"],correctAnswer:0,explanation:"妥当 (だとう) means 'valid / appropriate' (適切だ)."},{id:"v37",type:"paraphrase",question:"これは【やむを得ない】事情だ。",options:["仕方がない","とても嬉しい","とても悲しい","よくわからない"],correctAnswer:0,explanation:"やむを得ない means 'unavoidable / inevitable' (仕方がない)."},{id:"v38",type:"paraphrase",question:"【さっそく】始めてください。",options:["すぐに","あとで","ゆっくり","もう一度"],correctAnswer:0,explanation:"さっそく means 'at once / immediately' (すぐに)."},{id:"v39",type:"paraphrase",question:"彼は【めっきり】白髪が増えた。",options:["目立って","少し","全然","急に"],correctAnswer:0,explanation:"めっきり means 'remarkably / noticeably' (目立って)."}]},grammar:{timeLimit:30,questions:[{id:"g1",type:"grammar-fill",question:"彼は疲れている（　　）、無理をして働いている。",options:["にもかかわらず","につれて","にともなって","にこたえて"],correctAnswer:0,explanation:"〜にもかかわらず means 'despite / in spite of'."},{id:"g2",type:"grammar-fill",question:"このレストランは、味は（　　）、サービスが素晴らしい。",options:["ともかく","もちろん","ばかりか","どころか"],correctAnswer:0,explanation:"〜はともかく (setting aside / whether or not)."},{id:"g3",type:"grammar-fill",question:"いくら謝った（　　）、彼女は許してくれないだろう。",options:["ところで","ばかりに","せいで","おかげで"],correctAnswer:0,explanation:"〜たところで (even if / no matter how much) is followed by a negative or futile outcome."},{id:"g4",type:"grammar-fill",question:"彼の無責任な態度は、怒り（　　）。",options:["を禁じ得ない","を余儀なくされる","にほかならない","にすぎない"],correctAnswer:0,explanation:"〜を禁じ得ない (cannot help but / cannot suppress [emotion])."},{id:"g5",type:"grammar-fill",question:"あの真面目な彼が嘘をつく（　　）。",options:["はずがない","わけにはいかない","ことになっている","ものだ"],correctAnswer:0,explanation:"〜はずがない (it's impossible that)."},{id:"g6",type:"grammar-fill",question:"この仕事は、経験者（　　）難しい。",options:["であっても","にしたがって","にともなって","にかかわらず"],correctAnswer:0,explanation:"〜であっても (even for / even if one is)."},{id:"g7",type:"grammar-fill",question:"ストレスがたまると、病気になり（　　）。",options:["かねない","がたい","えない","っこない"],correctAnswer:0,explanation:"〜かねない (there is a fear that / might)."},{id:"g8",type:"grammar-fill",question:"日本に住んでいる（　　）、日本の法律を守らなければならない。",options:["以上は","うちに","あいだに","くせに"],correctAnswer:0,explanation:"〜以上は (now that / since)."},{id:"g9",type:"grammar-fill",question:"この問題は、専門家（　　）解決できない。",options:["でなければ","であれば","であっても","であれ"],correctAnswer:0,explanation:"〜でなければ (if not / unless one is)."},{id:"g10",type:"grammar-fill",question:"彼は来る（　　）と言っていたが、結局来なかった。",options:["ところで","ばかりに","からには","以上は"],correctAnswer:0,explanation:"〜たところで (even if / no matter how)."},{id:"g11",type:"grammar-fill",question:"こんなに雪が降っては、試合は中止せ（　　）。",options:["ざるを得ない","ずにはいられない","っこない","かねない"],correctAnswer:0,explanation:"〜ざるを得ない (have no choice but to)."},{id:"g12",type:"grammar-fill",question:"彼は親切（　　）、私が困っているといつも助けてくれる。",options:["なことに","なものだから","なばかりに","なせいで"],correctAnswer:0,explanation:"〜なことに (the [adjective] thing is... / to my [emotion]). 親切なことに = kindly / fortunately."},{id:"g13",type:"grammar-fill",question:"地球温暖化は、年々深刻になり（　　）。",options:["つつある","ようとしている","がちだ","ぎみだ"],correctAnswer:0,explanation:"〜つつある (is currently in the process of / is continuing to)."},{id:"g14",type:"grammar-fill",question:`次の文の ★ に入る最もよいものを一つ選びなさい。
あんな ___ ___ ★ ___ を ___ 信じられない。`,options:["ひどい","こと","する","なんて"],correctAnswer:1,explanation:"The correct order is: あんなひどいことをするなんて信じられない。 The star is 'こと'."},{id:"g15",type:"grammar-fill",question:"彼 ___ ___ ★ ___ 意見 ___ 反対だ。",options:["の","に","は","出した"],correctAnswer:1,explanation:"The correct order is: 彼の出した意見には反対だ。 The star is 'に'."},{id:"g16",type:"grammar-fill",question:"この ___ ___ ★ ___ なくても ___ 大丈夫です。",options:["薬","は","飲ま","毎日"],correctAnswer:3,explanation:"The correct order is: この薬は毎日飲まなくても大丈夫です。 The star is '毎日'."},{id:"g17",type:"grammar-fill",question:"どんな ___ ___ ★ ___ も ___ 諦めない。",options:["こと","が","あって","絶対に"],correctAnswer:2,explanation:"The correct order is: どんなことがあっても絶対に諦めない。 The star is 'あって'."},{id:"g18",type:"grammar-fill",question:"先生 ___ ___ ★ ___ て ___ 感謝しています。",options:["に","指導","いただい","して"],correctAnswer:3,explanation:"The correct order is: 先生に指導していただいて感謝しています。 The star is 'して'."}]},reading:{timeLimit:40,passages:[{id:"p1",text:"現代社会において、インターネットは私たちの生活に不可欠なものとなっている。情報の検索から買い物の決済、友人とのコミュニケーションに至るまで、様々な場面で利用されている。しかし、その利便性の裏には、個人情報の流出やネットいじめなど、深刻な問題も潜んでいる。我々は、インターネットの恩恵を享受する一方で、そのリスクも十分に認識し、適切に利用するリテラシーを身につける必要がある。",questions:[{id:"r1",type:"reading-comprehension",question:"筆者はインターネットについてどのように述べているか。",options:["利便性が高い反面、深刻なリスクも存在するため、適切に利用すべきだ。","利便性が高いため、リスクを気にする必要はない。","リスクが大きすぎるため、利用を制限すべきだ。","利便性よりもリスクの方が大きいので、利用をやめるべきだ。"],correctAnswer:0,explanation:"The passage states that while internet is highly convenient (恩恵を享受する), we must also recognize its risks (リスクも十分に認識し) and use it appropriately (適切に利用する)."},{id:"r2",type:"reading-comprehension",question:"文中の「そのリスク」とは具体的に何を指しているか。",options:["個人情報の流出やネットいじめなどの問題","情報の検索や買い物","友人とのコミュニケーション","インターネットの利便性"],correctAnswer:0,explanation:"The text mentions '個人情報の流出やネットいじめなど、深刻な問題' as the risks."}]},{id:"p2",text:"日本企業では、長年「終身雇用制度」と「年功序列」が重視されてきた。一度就職すれば定年まで雇用が保証され、年齢とともに給与が上がるという仕組みである。この制度は、社員の会社への忠誠心を高め、安定した経済成長を支える要因の一つであった。しかし、近年の経済のグローバル化や少子高齢化に伴い、この制度を維持することが難しくなりつつある。現在では、能力や成果に応じて給与を決める「成果主義」を導入する企業が増加している。",questions:[{id:"r3",type:"reading-comprehension",question:"「終身雇用制度」の長所として、筆者が挙げているのはどれか。",options:["社員の会社への忠誠心を高めたこと","能力に応じて給与が上がること","グローバル化に対応できること","若い社員の給与が高くなること"],correctAnswer:0,explanation:"The text says '社員の会社への忠誠心を高め... 安定した経済成長を支える要因の一つであった'."},{id:"r4",type:"reading-comprehension",question:"日本企業で「成果主義」を導入する企業が増えている理由として、最も適切なものはどれか。",options:["経済のグローバル化や少子高齢化によって、従来の制度の維持が困難になったため","社員が終身雇用制度を嫌がるようになったため","能力がない社員を辞めさせるため","会社への忠誠心をさらに高めるため"],correctAnswer:0,explanation:"The text attributes the difficulty of maintaining the old system to '近年の経済のグローバル化や少子高齢化' which leads to the introduction of merit-based systems."}]},{id:"p3",text:`【社内研修のお知らせ】
今年度の新入社員研修に加えて、中堅社員向けの「リーダーシップ研修」を実施いたします。
・対象：入社5年目〜10年目の社員
・日時：11月10日（金）または 11月17日（金）のいずれか1日（午前9時〜午後5時）
・場所：本社8階 大会議室
・申込：イントラネットの研修システムより、10月末までに各自で申し込むこと。
※業務の都合で参加が難しい場合は、事前に直属の部署長に相談してください。`,questions:[{id:"r5",type:"reading-comprehension",question:"この研修の対象者は誰か。",options:["入社5年目〜10年目の中堅社員","新入社員全員","全社員","部署長のみ"],correctAnswer:0,explanation:"The text specifies '対象：入社5年目〜10年目の社員'."},{id:"r6",type:"reading-comprehension",question:"研修への申し込みはどのように行うか。",options:["10月末までにイントラネットから各自で行う","直属の部署長にお願いする","11月10日までに各自で行う","当日、大会議室で直接申し込む"],correctAnswer:0,explanation:"The text says 'イントラネットの研修システムより、10月末までに各自で申し込むこと'."},{id:"r7",type:"reading-comprehension",question:"参加が難しい場合はどうすればよいか。",options:["事前に直属の部署長に相談する","申し込みをしなければよい","他の社員に代わりに出てもらう","後日、別の研修を受ける"],correctAnswer:0,explanation:"The text says '事前に直属の部署長に相談してください'."}]}]}},i={id:e,level:t,title:n,sections:o};export{i as default,e as id,t as level,o as sections,n as title};
